<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import type { QTableColumn } from 'quasar'
import { doAction } from '@/api'
import { useModalStore } from '@/stores/modal'
import PageHeader from '@/components/PageHeader.vue'

interface TaskConfig { ratio?: number | string; seeding_time?: number | string; upload_avs?: number | string; size?: number[]; tags?: string[]; savepath_key?: string; tracker_key?: string; qb_category?: string[]; qb_state?: string[]; tr_error_key?: string; tr_state?: string[] }
interface RemoveTask { id: number; name: string; enabled: number; action: number; interval: number | string; samedata: number; onlynastool: number; downloader: string; config: TaskConfig }
interface PreviewItem { name: string; site: string; size: number }

const modal = useModalStore()
const list = ref<RemoveTask[]>([])
const loading = ref(false)
const loadError = ref('')
const dialogVisible = ref(false)
const saving = ref(false)
const previewVisible = ref(false)
const previewLoading = ref(false)
const previewList = ref<PreviewItem[]>([])
const actionBusy = ref<number | null>(null)
const form = reactive({ tid: '' as string | number, name: '', action: 1, interval: '' as string | number, enabled: 0, samedata: 0, onlynastool: 1, ratio: '', seeding_time: '', upload_avs: '', size: '', tags: '', savepath_key: '', tracker_key: '', downloader: 'Qb', qb_state: '', qb_category: '', tr_state: '', tr_error_key: '' })

const actionOptions = [{ value: 1, label: '暂停种子', color: 'primary' }, { value: 2, label: '删除种子', color: 'warning' }, { value: 3, label: '删除种子及文件', color: 'negative' }]
const downloaderOptions = [{ value: 'Qb', label: 'Qbittorrent' }, { value: 'Tr', label: 'Transmission' }]
const qbStates = ['downloading', 'stalledDL', 'uploading', 'stalledUP', 'error', 'pausedDL', 'pausedUP', 'missingFiles', 'checkingDL', 'checkingUP', 'checkingResumeData', 'forcedDL', 'queuedDL', 'forcedUP', 'queuedUP', 'allocating', 'metaDL', 'moving', 'unknown']
const trStates = ['downloading', 'seeding', 'download_pending', 'seed_pending', 'checking', 'check_pending', 'stopped']
const qbStateValues = computed<string[]>({ get: () => form.qb_state ? form.qb_state.split(';').filter(Boolean) : [], set: (value) => { form.qb_state = value.join(';') } })
const trStateValues = computed<string[]>({ get: () => form.tr_state ? form.tr_state.split(';').filter(Boolean) : [], set: (value) => { form.tr_state = value.join(';') } })
const columns: QTableColumn<RemoveTask>[] = [
  { name: 'state', label: '状态', field: 'enabled', align: 'left' },
  { name: 'name', label: '任务名称', field: 'name', align: 'left', sortable: true },
  { name: 'downloader', label: '下载器', field: 'downloader', align: 'left' },
  { name: 'action', label: '动作', field: 'action', align: 'left' },
  { name: 'interval', label: '刷新间隔', field: 'interval', align: 'left' },
  { name: 'conditions', label: '条件摘要', field: 'config', align: 'left' },
  { name: 'actions', label: '操作', field: 'id', align: 'right' }
]

function actionLabel(value: number) { return actionOptions.find((item) => item.value === value)?.label || '' }
function actionColor(value: number) { return actionOptions.find((item) => item.value === value)?.color || 'grey-7' }
function downloaderLabel(value: string) { return downloaderOptions.find((item) => item.value === value)?.label || value }
function conditionSummary(row: RemoveTask) { const config = row.config || {}; const values = [`间隔 ${row.interval} 分钟`]; if (config.ratio) values.push(`分享率 ≥ ${config.ratio}`); if (config.seeding_time) values.push(`做种 ≥ ${config.seeding_time} 小时`); if (config.size?.length) values.push(`大小 ${config.size[0]}-${config.size[config.size.length - 1]} GB`); return values.join(' · ') }

onMounted(load)
async function load() { if (loading.value) return; loading.value = true; loadError.value = ''; try { const response = await doAction<{ code: number; msg?: string; detail: Record<string, RemoveTask> }>('get_torrent_remove_task', {}); if (response.code === 0) list.value = response.detail ? Object.values(response.detail) : []; else loadError.value = response.msg || '获取删种任务失败' } catch (error) { loadError.value = error instanceof Error ? error.message : '获取删种任务失败' } finally { loading.value = false } }
function resetForm() { Object.assign(form, { tid: '', name: '', action: 1, interval: '', enabled: 0, samedata: 0, onlynastool: 1, ratio: '', seeding_time: '', upload_avs: '', size: '', tags: '', savepath_key: '', tracker_key: '', downloader: 'Qb', qb_state: '', qb_category: '', tr_state: '', tr_error_key: '' }) }
function openAdd() { resetForm(); dialogVisible.value = true }
async function openEdit(row: RemoveTask) { try { const response = await doAction<{ code: number; msg?: string; detail: RemoveTask }>('get_torrent_remove_task', { tid: row.id }); if (response.code !== 0 || !response.detail) { modal.error(response.msg || '获取任务详情失败'); return }; const detail = response.detail; const config = detail.config || {}; resetForm(); Object.assign(form, { tid: detail.id, name: detail.name, action: detail.action, interval: detail.interval, enabled: detail.enabled, samedata: detail.samedata, onlynastool: detail.onlynastool, downloader: detail.downloader || 'Qb', ratio: config.ratio != null ? String(config.ratio) : '', seeding_time: config.seeding_time != null ? String(config.seeding_time) : '', upload_avs: config.upload_avs != null ? String(config.upload_avs) : '', size: config.size?.length ? `${config.size[0]}-${config.size[config.size.length - 1]}` : '', tags: config.tags?.join(';') || '', savepath_key: config.savepath_key || '', tracker_key: config.tracker_key || '', qb_state: config.qb_state?.join(';') || '', qb_category: config.qb_category?.join(';') || '', tr_state: config.tr_state?.join(';') || '', tr_error_key: config.tr_error_key || '' }); dialogVisible.value = true } catch (error) { modal.error(error instanceof Error ? error.message : '获取任务详情失败') } }
async function submit() { if (!form.name.trim()) { modal.warning('名称不能为空'); return }; if (!form.interval || isNaN(Number(form.interval))) { modal.warning('运行间隔必须为数字'); return }; const numericFields: Array<[string, string]> = [['ratio', '分享率'], ['seeding_time', '做种时间'], ['upload_avs', '平均上传速度']]; for (const [key, label] of numericFields) if (form[key as keyof typeof form] && isNaN(Number(form[key as keyof typeof form]))) { modal.warning(`${label}必须为数字`); return }; saving.value = true; try { const response = await doAction<{ code: number; msg?: string }>('update_torrent_remove_task', { tid: form.tid, name: form.name.trim(), action: form.action, interval: form.interval, enabled: form.enabled, samedata: form.samedata, onlynastool: form.onlynastool, ratio: form.ratio, seeding_time: form.seeding_time, upload_avs: form.upload_avs, size: form.size, tags: form.tags, savepath_key: form.savepath_key, tracker_key: form.tracker_key, downloader: form.downloader, qb_state: form.qb_state, qb_category: form.qb_category, tr_state: form.tr_state, tr_error_key: form.tr_error_key }); if (response.code === 0) { dialogVisible.value = false; modal.success('保存成功'); await load() } else modal.error(response.msg || '保存失败') } catch (error) { modal.error(error instanceof Error ? error.message : '保存失败') } finally { saving.value = false } }
async function remove(row: RemoveTask) { if (!await modal.confirm(`确认删除删种任务「${row.name}」？`, '删除删种任务')) return; try { const response = await doAction<{ code: number; msg?: string }>('delete_torrent_remove_task', { tid: row.id }); if (response.code === 0) { modal.success('删除成功'); await load() } else modal.error(response.msg || '删除失败') } catch (error) { modal.error(error instanceof Error ? error.message : '删除失败') } }
async function run(row: RemoveTask) { if (actionBusy.value) return; actionBusy.value = row.id; try { const response = await doAction<{ code: number; msg?: string }>('auto_remove_torrents', { tid: row.id }); if (response.code === 0) { modal.success('任务运行完成'); await load() } else modal.error(response.msg || '任务运行失败') } catch (error) { modal.error(error instanceof Error ? error.message : '任务运行失败') } finally { actionBusy.value = null } }
async function preview(row: RemoveTask) { previewVisible.value = true; previewLoading.value = true; previewList.value = []; try { const response = await doAction<{ code: number; msg?: string; data: PreviewItem[] }>('get_remove_torrents', { tid: row.id }); if (response.code === 0) previewList.value = response.data || []; else modal.warning(response.msg || '未获取到符合处理条件的种子') } catch (error) { modal.error(error instanceof Error ? error.message : '预览失败') } finally { previewLoading.value = false } }
function fmtSize(size: number) { return `${(size / 1024 / 1024 / 1024).toFixed(2)} GB` }
</script>

<template>
  <div class="page-shell torrent-remove-view">
    <PageHeader title="自动删种任务" description="按条件自动暂停或删除下载器中的种子"><template #actions><q-btn color="primary" unelevated icon="add" label="新增删种任务" @click="openAdd" /><q-btn outline icon="refresh" label="刷新" :loading="loading" @click="load" /></template></PageHeader>
    <q-banner v-if="loadError" class="q-mb-md" rounded inline-actions dense><template #avatar><q-icon name="error_outline" color="negative" /></template>{{ loadError }}<template #action><q-btn flat color="primary" label="重试" @click="load" /></template></q-banner>
    <q-card flat bordered class="task-card">
      <q-table v-if="!$q.screen.lt.sm" flat :rows="list" :columns="columns" row-key="id" :loading="loading" hide-pagination :rows-per-page-options="[0]" no-data-label="没有自动删种任务"><template #body-cell-state="slotProps"><q-td :props="slotProps"><q-badge :color="slotProps.row.enabled ? 'positive' : 'grey-6'" :label="slotProps.row.enabled ? '运行' : '停用'" /></q-td></template><template #body-cell-downloader="slotProps"><q-td :props="slotProps"><q-badge outline color="primary" :label="downloaderLabel(slotProps.row.downloader)" /></q-td></template><template #body-cell-action="slotProps"><q-td :props="slotProps"><q-badge :color="actionColor(slotProps.row.action)" :label="actionLabel(slotProps.row.action)" /></q-td></template><template #body-cell-conditions="slotProps"><q-td :props="slotProps"><span class="text-caption text-secondary">{{ conditionSummary(slotProps.row) }}</span></q-td></template><template #body-cell-actions="slotProps"><q-td :props="slotProps"><div class="row justify-end q-gutter-xs"><q-btn flat dense color="positive" icon="bolt" label="运行" :loading="actionBusy === slotProps.row.id" @click="run(slotProps.row)" /><q-btn flat dense color="primary" icon="visibility" label="预览" @click="preview(slotProps.row)" /><q-btn flat dense color="primary" icon="edit" label="编辑" @click="openEdit(slotProps.row)" /><q-btn flat dense color="negative" icon="delete" label="删除" @click="remove(slotProps.row)" /></div></q-td></template></q-table>
      <div v-else class="mobile-task-list"><q-card v-for="row in list" :key="row.id" flat bordered class="task-item"><q-card-section><div class="row items-center"><div class="text-subtitle1 text-weight-medium ellipsis">{{ row.name }}</div><q-space /><q-badge :color="row.enabled ? 'positive' : 'grey-6'" :label="row.enabled ? '运行' : '停用'" /></div><div class="row items-center q-gutter-xs q-mt-sm"><q-badge outline color="primary" :label="downloaderLabel(row.downloader)" /><q-badge :color="actionColor(row.action)" :label="actionLabel(row.action)" /></div><div class="text-caption text-secondary q-mt-sm">{{ conditionSummary(row) }}</div></q-card-section><q-separator /><q-card-actions align="right"><q-btn flat color="positive" icon="bolt" label="运行" :loading="actionBusy === row.id" @click="run(row)" /><q-btn flat color="primary" icon="visibility" label="预览" @click="preview(row)" /><q-btn flat color="primary" icon="edit" label="编辑" @click="openEdit(row)" /><q-btn flat color="negative" icon="delete" label="删除" @click="remove(row)" /></q-card-actions></q-card><q-item v-if="!loading && !list.length"><q-item-section class="text-center text-secondary q-py-xl">没有自动删种任务</q-item-section></q-item></div>
    </q-card>

    <q-dialog v-model="dialogVisible" :maximized="$q.screen.lt.sm" :full-width="!$q.screen.lt.sm"><q-card class="editor-dialog"><q-card-section class="row items-center"><div class="text-h6">{{ form.tid ? '编辑删种任务' : '新增删种任务' }}</div><q-space /><q-btn flat round dense icon="close" aria-label="关闭" v-close-popup /></q-card-section><q-separator /><q-card-section class="editor-form"><div class="form-section"><div class="section-title">基础设置</div><div class="form-grid"><q-input v-model="form.name" outlined label="名称" placeholder="别名" :disable="saving" /><q-select v-model="form.action" outlined label="动作" :options="actionOptions" emit-value map-options :disable="saving" /></div><div class="form-grid"><q-input v-model="form.interval" outlined type="number" label="运行间隔（分钟）" placeholder="分钟" :disable="saving" /><q-select v-model="form.enabled" outlined label="状态" :options="[{ value: 1, label: '启用' }, { value: 0, label: '停用' }]" emit-value map-options :disable="saving" /></div><div class="form-grid"><q-select v-model="form.samedata" outlined label="处理辅种" :options="[{ value: 0, label: '否' }, { value: 1, label: '是' }]" emit-value map-options :disable="saving" /><q-select v-model="form.onlynastool" outlined label="只管理 NAStool 添加" :options="[{ value: 0, label: '否' }, { value: 1, label: '是' }]" emit-value map-options :disable="saving" /></div></div><div class="form-section"><div class="section-title">条件设置</div><div class="form-grid"><q-input v-model="form.ratio" outlined label="分享率" placeholder="保留一位小数" :disable="saving" /><q-input v-model="form.seeding_time" outlined label="做种时间（小时）" placeholder="小时" :disable="saving" /></div><div class="form-grid"><q-input v-model="form.upload_avs" outlined label="平均上传速度（KB/s）" placeholder="KB/s" :disable="saving" /><q-input v-model="form.size" outlined label="种子大小（GB）" placeholder="如 1-10" :disable="saving" /></div><div class="form-grid"><q-input v-model="form.tags" outlined label="标签" placeholder="多个标签用 ; 分隔" :disable="saving" /><q-input v-model="form.savepath_key" outlined label="保存路径关键词" placeholder="支持正则表达式" :disable="saving" /></div><q-input v-model="form.tracker_key" outlined label="Tracker 关键词" placeholder="支持正则表达式" :disable="saving" /></div><div class="form-section"><div class="section-title">下载器</div><q-option-group v-model="form.downloader" :options="downloaderOptions" type="radio" inline color="primary" :disable="saving" /><template v-if="form.downloader === 'Qb'"><div class="form-grid"><q-select v-model="qbStateValues" outlined multiple use-chips label="种子状态" :options="qbStates" :disable="saving" /><q-input v-model="form.qb_category" outlined label="分类" placeholder="多个分类用 ; 分隔" :disable="saving" /></div></template><template v-else><div class="form-grid"><q-select v-model="trStateValues" outlined multiple use-chips label="种子状态" :options="trStates" :disable="saving" /><q-input v-model="form.tr_error_key" outlined label="错误信息关键词" placeholder="支持正则表达式" :disable="saving" /></div></template></div></q-card-section><q-separator /><q-card-actions align="right" class="dialog-actions"><q-btn flat label="取消" :disable="saving" v-close-popup /><q-btn color="primary" unelevated label="保存" :loading="saving" @click="submit" /></q-card-actions></q-card></q-dialog>
    <q-dialog v-model="previewVisible" :maximized="$q.screen.lt.sm" :full-width="!$q.screen.lt.sm"><q-card class="preview-dialog"><q-card-section class="row items-center"><div class="text-h6">预处理种子列表</div><q-space /><q-btn flat round dense icon="close" aria-label="关闭" v-close-popup /></q-card-section><q-separator /><q-card-section><q-inner-loading :showing="previewLoading"><q-spinner-dots color="primary" size="36px" /></q-inner-loading><div v-if="previewList.length" class="preview-count">共 {{ previewList.length }} 个种子</div><q-table v-if="previewList.length" flat :rows="previewList" :columns="[{ name: 'name', label: '种子名称', field: 'name', align: 'left' }, { name: 'site', label: '站点', field: 'site', align: 'left' }, { name: 'size', label: '大小', field: 'size', align: 'left' }]" row-key="name" hide-pagination :rows-per-page-options="[0]" class="preview-table"><template #body-cell-size="slotProps"><q-td :props="slotProps">{{ fmtSize(slotProps.row.size) }}</q-td></template></q-table><div v-else-if="!previewLoading" class="empty-preview"><q-icon name="inbox" size="40px" /><div>未获取到符合处理条件的种子</div></div></q-card-section><q-separator /><q-card-actions align="right" class="dialog-actions"><q-btn color="primary" unelevated label="关闭" v-close-popup /></q-card-actions></q-card></q-dialog>
  </div>
</template>

<style scoped>
.torrent-remove-view { max-width: 1600px; margin: 0 auto; }
.task-card { overflow: hidden; }
.mobile-task-list { display: grid; gap: 10px; padding: 12px; }
.task-item { border-radius: 12px; }
.editor-dialog, .preview-dialog { width: min(820px, calc(100vw - 32px)); max-width: none; border-radius: 16px; }
.preview-dialog { width: min(760px, calc(100vw - 32px)); }
.editor-form { display: grid; gap: 20px; }
.form-section { display: grid; gap: 14px; }
.section-title { padding-bottom: 4px; border-bottom: 1px solid var(--border-subtle); color: var(--text-primary); font-size: 14px; font-weight: 650; }
.form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.dialog-actions { gap: 8px; }
.preview-count { margin-bottom: 10px; color: var(--text-secondary); font-size: 13px; }
.empty-preview { display: grid; justify-items: center; gap: 8px; padding: 56px 16px; color: var(--text-secondary); }
@media (max-width: 599px) { .editor-dialog, .preview-dialog { width: 100%; min-height: 100dvh; border-radius: 0; } .form-grid { grid-template-columns: 1fr; gap: 16px; } .dialog-actions { position: sticky; bottom: 0; padding: 10px 16px calc(10px + var(--safe-bottom)); background: var(--surface); } .dialog-actions :deep(.q-btn) { min-height: 44px; } }
</style>
